const paragraphList = list => list.map(text=>`<p>${e(text)}</p>`).join('');
function toolPage(page,index){
  const name=names[page.id];
  const note = page.id==='webcam'?'Your camera starts only when you choose.':page.id==='microphone'?'Your microphone starts only when you choose.':page.id==='headphone'?'Set your device volume low before playing.':'Your inputs stay in this browser.';
  const extraGuide = page.id==='headphone' ? `<section class="headphone-guide"><h2>A second listening check</h2><p>This channel test answers a specific question: does the intended left or right cue reach you? For a longer listening exercise, this video provides another route to test your headphones.</p><div class="video-embed"><iframe src="https://www.youtube.com/embed/91BUM3WhCfo" title="Headphone test video on YouTube" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div><p class="headphone-guide__note">The player is provided by YouTube and may set or receive data under YouTube’s policies. Comfort, fit, noise isolation, battery life and build quality still need to be assessed in your normal use—not inferred from a browser test.</p></section>` : page.id==='movie' ? `<section class="headphone-guide"><h2>Check a real video player</h2><p>Run the local motion pattern above, then use this optional YouTube video to check playback in an embedded player.</p><div class="video-embed"><iframe src="https://www.youtube.com/embed/KtZMk-w713w" title="Movie display test video on YouTube" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div><p class="headphone-guide__note">YouTube provides this player and may set or receive data under its policies. Smooth playback here does not measure monitor refresh rate or video-decoder performance.</p></section>` : '';
  const body=`<main id="main" class="container"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">All tests</a><span aria-hidden="true">/</span><span>${name}</span></nav><div class="tool-heading"><div><p class="eyebrow">${e(page.category)}</p><h1>${name}</h1><p>${e(page.intro)}</p></div><span class="tool-index">INSTRUMENT 0${index+1} / 06</span></div><section class="tool-frame" aria-label="Interactive ${e(name.toLowerCase())}"><div class="tool-frame-header"><span>TI—0${index+1} &nbsp; ${name}</span><span>${lockIcon} LOCAL TO YOUR DEVICE</span></div><div id="tool-root" data-tool="${page.id}"><p class="tool-loading">Preparing the test…</p></div><noscript><p class="noscript">This interactive test needs JavaScript. Enable it to use the tool. The instructions and troubleshooting below are available without it.</p></noscript></section><div class="tool-bottom-note"><span>${note}</span><a href="#troubleshooting">Something not working?</a></div><div class="tool-content"><nav class="on-this-page" aria-label="On this page"><p>IN THIS GUIDE</p><a href="#how-to">How to use this test</a><a href="#method">What we check</a><a href="#limits">What it can’t tell you</a><a href="#troubleshooting">Troubleshooting</a><a href="#questions">Common questions</a></nav><article class="article-body">${extraGuide}<section id="how-to"><h2>How to use this test</h2><ol class="steps">${page.steps.map(step=>`<li><div><h3>${e(step.title)}</h3><p>${e(step.text)}</p></div></li>`).join('')}</ol></section><section id="method"><h2>What we check</h2>${paragraphList(page.method)}</section><section id="limits" class="limits"><h2>What this test can’t tell you</h2>${paragraphList(page.limits)}</section><section id="troubleshooting"><h2>Something not working?</h2>${page.troubleshooting.map(item=>`<details><summary>${e(item.title)}</summary><p>${e(item.text)}</p></details>`).join('')}</section><section id="questions"><h2>Common questions</h2>${page.faqs.map(item=>`<details><summary>${e(item.question)}</summary><p>${e(item.answer)}</p></details>`).join('')}</section><div class="related"><h2>While you’re here</h2><div class="related-links">${page.related.map(id=>`<a href="/${id}-test/">${names[id]} <span aria-hidden="true">↗</span></a>`).join('')}</div></div></article></div></main>`;
  const relatedLinks = page.related.map(id => { const related = pages.find(item => item.id === id); return `<a href="/${related?.slug || `${id}-test`}/">${names[id]}</a>`; }).join('');
  const displayBody = body.replace('<article class="article-body">', '<article class="article-body">'+(page.category === 'Brain games' ? '<p><a href="/brain-tests/">Explore all brain games</a></p>' : '')).replace('<div class="tool-heading">', '<div class="tool-heading"><div class="tool-page-art" aria-hidden="true">'+icons[page.id]+'</div>').replace(/<span class="tool-index">.*?<\/span>/, '').replace(/TI—0\d+\s*&nbsp;\s*/, '').replace(/<div class="related-links">.*?<\/div>/, `<div class="related-links">${relatedLinks}</div>`).replaceAll(' <span aria-hidden="true">↗</span>', '');
  const breadcrumb={"@context":"https://schema.org","@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:'All tests',item:'https://test.institute/'},{"@type":"ListItem",position:2,name,item:`https://test.institute/${page.slug}/`}]};
  return layout(page.title,page.description,`/${page.slug}/`,displayBody,`${page.category === 'Brain games' ? '<link rel="stylesheet" href="/assets/brain-tools.css">' : ''}<link rel="stylesheet" href="/assets/input-tools.css"><link rel="stylesheet" href="/assets/media-tools.css"><script type="application/ld+json">${JSON.stringify(breadcrumb).replaceAll('<','\\u003c')}</script>`);
}
const support = {
 'how-we-test':{title:'How we test',description:'What Test Institute observes, how our browser tools work, and the limits behind every result.',lead:'Useful tests start with an honest question: what can this browser actually tell us?',body:`<h2>Observe first. Explain second.</h2><p>A camera preview confirms that your browser receives video. A key lighting up confirms that a keyboard event reached this page. Those are useful observations. Neither is a certificate that the hardware is fault-free.</p><p>We put the test first, explain the method underneath, and make the next troubleshooting step easy to find. A limitation is part of the result.</p><h2>Three kinds of results</h2><p><strong>Browser-reported settings.</strong> Camera dimensions, frame-rate settings, and microphone sample rate come from the active stream. They describe what the browser reports, not a laboratory measurement.</p><p><strong>Observed input.</strong> Key presses, pointer events, touches and controller values show what reaches this page. Operating-system settings and browser behavior affect them.</p><p><strong>Your observation.</strong> Headphone channel checks and screen patterns need you to listen or look. We label your confirmations rather than deciding for you.</p><h2>Designed to stay local</h2><p>Camera video, microphone samples, keyboard events, pointer input, touch input and controller values are not uploaded. The Wi-Fi speed test is the exception: when run, it sends a generated 2 MB sample to this site solely to time the upload. There are no advertising scripts, analytics beacons, or user accounts in this version.</p><h2>When a test cannot run</h2><p>Permission denied, unsupported features, and missing hardware get a specific message wherever the browser exposes that distinction. A page cannot override an operating-system restriction. Try the suggested checks and compare with another app before concluding that hardware is faulty.</p><h2>What we don’t claim</h2><p>Test Institute is a browser utility collection, not an accredited laboratory. These tools do not diagnose hearing, eyesight, or health; certify equipment; or measure calibrated acoustic or display performance.</p><p><a href="/#tests">Choose a test</a></p>`},
 'about':{title:'Small tests for everyday things.',description:'Test Institute makes straightforward browser tools for checking your everyday devices.',lead:'Technology should leave you with fewer questions. We’re here to help with a few of them.',body:`<h2>A check before the important moment</h2><p>Before a call, after connecting a new keyboard, or when one headphone goes quiet, a quick check can help you decide what to do. Test Institute brings those checks together in a simple, familiar place.</p><h2>The tool and the explanation</h2><p>Each page pairs a working browser tool with instructions, a clear method, and practical troubleshooting. You can start immediately or read into the details. There is no account to create and no software to install.</p><h2>Why “Institute”?</h2><p>For us, it means taking small questions seriously: explaining our methods, stating our limits, and avoiding claims our tools cannot support. It is a name, not a claim of accreditation.</p><p><a href="/how-we-test/">Read about our methods →</a></p>`},
 'privacy':{title:'Your tests stay with you.',description:'How Test Institute handles camera previews, microphone recordings, and input data.',lead:'Most tools process their test inputs in your browser. The Wi-Fi speed test sends only a generated timing sample when you start it.',body:`<h2>Camera and microphone</h2><p>Camera and microphone access starts only after you choose Start. Your browser controls permission. The webcam test does not record video. The microphone test records a short sample only when you explicitly choose Record, and keeps that sample in browser memory for local playback.</p><p>Stop releases access. Leaving or hiding a media test stops the session. Stopping the microphone also removes its local recording. You can revoke a remembered permission in your browser’s site settings.</p><h2>Keyboard, pointer, touch and controller input</h2><p>The keyboard test reads events only while its test area is active. The mouse and touchscreen tests observe only their marked areas. The gamepad test reads controller values the browser exposes while the page is open. Reset clears the visible results, and none of these inputs are stored or sent.</p><h2>Wi-Fi speed sample</h2><p>When you choose Measure speed, the Wi-Fi speed test downloads a bundled 2 MB file and uploads a generated 2 MB byte sample to this site’s measurement endpoint. It does not upload a file, camera feed, microphone recording or keyboard input from your device.</p><h2>No accounts or tracking scripts</h2><p>This version has no account system, advertising, analytics, cookies, or persistent test history. Search filters the directory locally. Fonts and scripts are served with the site, without third-party font services.</p><h2>Ordinary website requests</h2><p>Your browser still requests the page and its assets from the web host. Like other website requests, these expose connection information such as your IP address and requested URL to that host. This description concerns the tools’ behavior; hosting-level logging depends on the deployment provider.</p><h2>Your controls</h2><p>Use Stop or Cancel inside a tool, close the page, or revoke site permissions in your browser. There is no saved profile or cloud recording to delete.</p>`},
 'accessibility':{title:'A test you can use.',description:'Keyboard controls, reduced motion, and accessibility features in Test Institute.',lead:'Clear controls and useful explanations should be available however you navigate.',body:`<h2>Keyboard navigation</h2><p>Use Tab to move between links and controls. A visible outline shows focus. Every page includes a skip link to its main content. For the keyboard instrument, activate the test area first; Escape stops capture and Tab remains available to leave it.</p><h2>Motion and color</h2><p>Decorative transitions respect your device’s reduced-motion preference. Status messages use words, not color alone. Screen inspection uses static patterns, without flashing sequences.</p><h2>Audio and camera controls</h2><p>No audio plays automatically and no device access is requested on page load. Start, Stop, and Cancel controls are labeled. Browser settings and device support may limit which tools are available.</p><h2>Limits of the tests</h2><p>A visual screen inspection needs sight, and an audio-channel confirmation needs hearing. The explanations remain available to read, but those tasks do not have an equivalent automatic verdict. The camera test displays a preview and browser settings without making a judgment about visual quality.</p><h2>Readable content</h2><p>Pages reflow on small screens and at larger text sizes. Instructions and methods are ordinary HTML and stay readable even when a browser feature or the interactive script is unavailable.</p>`}
 ,'imprint':{title:'Imprint',description:'Legal notice and contact details for Test Institute.',lead:'Information pursuant to § 5 DDG.',body:`<h2>Service provider</h2><p>Andreas Dittes<br>Bautzener Str. 35<br>10829 Berlin<br>Germany</p><h2>Contact</h2><p>Email: <a href="mailto:test.institute@dittes.info">test.institute@dittes.info</a></p><h2>Responsible for content</h2><p>Andreas Dittes<br>Bautzener Str. 35<br>10829 Berlin<br>Germany</p>`}
};
await mkdir(out,{recursive:true});
await mkdir(resolve(out,'brain-tests'),{recursive:true});
const brainCollection = pages.filter(page => page.category === 'Brain games');
const brainHub = `<main id="main" class="container"><div class="tool-heading"><div><h1>Online brain tests</h1><p>Six short games for memory, reaction, aim and typing. Pick one, learn the rules, and compare your own runs. No account, download or saved leaderboard.</p></div></div><div class="tool-grid">${brainCollection.map(card).join('')}</div><article class="reading-page"><h2>Choose the task, not a label</h2><p>Remembering a sequence is different from recognizing a word. Hitting a target combines seeing, moving and clicking; a reaction test keeps the target still. Typing adds a familiar skill and a speed–accuracy trade-off. A single score cannot stand in for all of these.</p><h2>Make comparisons useful</h2><p>Keep the same device, input method and browser size. Learn the rules before treating a run as a reference, and take breaks when you feel tired. Practice can improve your performance at the game; it does not establish a change in general intelligence.</p><h2>What these games are not</h2><p>These are informal online brain games, not validated cognitive assessments or medical screenings. We do not assign an IQ, a brain age or a percentile. Scores stay in page memory and disappear on reset or navigation.</p><h2>Other simple games worth exploring</h2><p>A visual memory grid would test locations without sequence order. A colour-word challenge could ask you to select ink colour rather than read the word. Those are possible future additions; the six playable tests above are available now.</p><p><a href="/">Browse all device tests</a></p></article></main>`;
await writeFile(resolve(out,'brain-tests','index.html'),layout('Free Online Brain Tests — Memory, Reaction & Typing | Test Institute','Play six free online brain games: reaction time, sequence memory, aim, number memory, verbal memory and typing. Local scores, clear rules and no account.','/brain-tests/',brainHub));
await cp(resolve(base,'assets'),resolve(out,'assets'),{recursive:true});
await writeFile(resolve(out,'assets','speed-sample.bin'),Buffer.alloc(2 * 1024 * 1024, 97));
await cp(resolve(base,'tokens.css'),resolve(out,'tokens.css'));
await writeFile(resolve(out,'index.html'),layout('Test Institute — Simple Online Device Tests','Check your camera, microphone, headphones, keyboard, mouse, screen, touchscreen or controller. Practical browser tools with clear results and useful troubleshooting.','/',cleanRebuiltHome));
for (let i=0;i<pages.length;i++) { await mkdir(resolve(out,pages[i].slug),{recursive:true});await writeFile(resolve(out,pages[i].slug,'index.html'),toolPage(pages[i],i)); }
for(const [slug,page] of Object.entries(support)){await mkdir(resolve(out,slug),{recursive:true});await writeFile(resolve(out,slug,'index.html'),layout(`${page.title} · Test Institute`,page.description,`/${slug}/`,`<main id="main" class="container"><article class="reading-page"><p class="eyebrow">TEST INSTITUTE / ${slug.replaceAll('-',' ')}</p><h1>${page.title}</h1><p class="lead">${page.lead}</p>${page.body}</article></main>`));}
await writeFile(resolve(out,'404.html'),layout('Page not found · Test Institute','Find the device test you need.','/404.html','<main id="main" class="container"><article class="reading-page"><p class="eyebrow">404 / NOT FOUND</p><h1>That test isn’t here.</h1><p class="lead">The page may have moved. Find your next check in the test directory.</p><a class="button" href="/#tests">Explore all tests</a></article></main>','<meta name="robots" content="noindex">'));
const urls=['/','/brain-tests/',...pages.map(p=>`/${p.slug}/`),...Object.keys(support).map(slug=>`/${slug}/`)];
await writeFile(resolve(out,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map(url=>`<url><loc>https://test.institute${url}</loc></url>`).join('')}</urlset>`);
await writeFile(resolve(out,'robots.txt'),'User-agent: *\nAllow: /\nSitemap: https://test.institute/sitemap.xml\n');
await cp(resolve(base,'CNAME'),resolve(out,'CNAME'));
await writeFile(resolve(out,'.nojekyll'),'');
console.log(`Built ${urls.length} pages + 404 in dist/`);
// GitHub Pages in this repository serves the root. Export only known build
// outputs, never repository metadata or arbitrary files from a copied checkout.
if (process.argv.includes('--site-root')) {
  for (const url of urls) {
    const relative = `${url.slice(1)}index.html`;
    await mkdir(resolve(base, `.${url}`), { recursive: true });
    await cp(resolve(out, relative), resolve(base, relative));
  }
  for (const relative of ['404.html', 'sitemap.xml', 'robots.txt', '.nojekyll', 'assets/speed-sample.bin']) {
    await cp(resolve(out, relative), resolve(base, relative));
  }
  console.log('Updated published HTML and generated assets at the repository root. Git metadata is untouched.');
}
